import { _decorator, Component, EventMouse, EventTouch, Input, UITransform, Vec2, Vec3, Node } from 'cc';
import type { Bus } from '../Engine/Bus';
import { HallEvents } from './HallEvents';

const { ccclass } = _decorator;

const TAP_TOLERANCE_SQ = 100;
const WHEEL_ZOOM_STEP = 0.1;

@ccclass('HallInputHandler')
export class HallInputHandler extends Component {
    private _bus: Bus = null!;
    private _targetUITransform: UITransform = null!;

    // 触摸状态
    private _isTouchDragging = false;
    private _activeTouchId = -1;
    private _lastPinchDist = 0;

    // 鼠标状态
    private _isMouseDragging = false;

    // 复用对象
    private _touchUIPos = new Vec2();
    private _startUIPos = new Vec2();
    private _tempUILoc = new Vec2();
    private _inputWorldPos = new Vec3();
    private _targetLocalPos = new Vec3();

    setup(bus: Bus, targetNode: Node) {
        this._bus = bus;
        this._targetUITransform = targetNode.getComponent(UITransform)!;
        this._registerInputListeners();
    }

    onDestroy() {
        this._unregisterInputListeners();
    }

    // =========================================================
    //  监听注册 / 注销
    // =========================================================
    private _registerInputListeners(): void {
        this.node.on(Node.EventType.TOUCH_START, this._onTouchStart, this);
        this.node.on(Node.EventType.TOUCH_MOVE, this._onTouchMove, this);
        this.node.on(Node.EventType.TOUCH_END, this._onTouchEnd, this);
        this.node.on(Node.EventType.TOUCH_CANCEL, this._onTouchEnd, this);

        this.node.on(Node.EventType.MOUSE_DOWN, this._onMouseDown, this);
        this.node.on(Node.EventType.MOUSE_MOVE, this._onMouseMove, this);
        this.node.on(Node.EventType.MOUSE_UP, this._onMouseUp, this);

        // ★ 新增：鼠标滚轮
        this.node.on(Node.EventType.MOUSE_WHEEL, this._onMouseWheel, this);
    }

    private _unregisterInputListeners(): void {
        this.node.off(Node.EventType.TOUCH_START, this._onTouchStart, this);
        this.node.off(Node.EventType.TOUCH_MOVE, this._onTouchMove, this);
        this.node.off(Node.EventType.TOUCH_END, this._onTouchEnd, this);
        this.node.off(Node.EventType.TOUCH_CANCEL, this._onTouchEnd, this);

        this.node.off(Node.EventType.MOUSE_DOWN, this._onMouseDown, this);
        this.node.off(Node.EventType.MOUSE_MOVE, this._onMouseMove, this);
        this.node.off(Node.EventType.MOUSE_UP, this._onMouseUp, this);

        this.node.off(Node.EventType.MOUSE_WHEEL, this._onMouseWheel, this);
    }

    // =========================================================
    //  触摸：单指拖动 / 双指缩放 / 点击
    // =========================================================
    private _onTouchStart(e: EventTouch): void {
        const touches = e.getAllTouches();
        if (touches.length === 1) {
            this._activeTouchId = touches[0].getID();
            this._isTouchDragging = false;
            e.getUILocation(this._tempUILoc);
            this._startUIPos.set(this._tempUILoc.x, this._tempUILoc.y);
        }
    }

    private _onTouchMove(e: EventTouch): void {
        const touches = e.getAllTouches();

        if (touches.length >= 2) {
            // 双指缩放
            const p1 = touches[0].getUILocation();
            const p2 = touches[1].getUILocation();
            const currentDist = Math.sqrt(
                (p2.x - p1.x) ** 2 + (p2.y - p1.y) ** 2
            );

            if (this._lastPinchDist > 0) {
                const factor = currentDist / this._lastPinchDist;
                this._bus.emit(HallEvents.INPUT_PINCH, factor);
            }
            this._lastPinchDist = currentDist;
            this._isTouchDragging = true;

        } else if (touches.length === 1 && touches[0].getID() === this._activeTouchId) {
            // 单指拖动
            const delta = e.getUIDelta();
            if (Math.abs(delta.x) > 0 || Math.abs(delta.y) > 0) {
                this._isTouchDragging = true;
                this._bus.emit(HallEvents.INPUT_SINGLE_DRAG, delta.x, delta.y);
            }
        }
    }

    private _onTouchEnd(e: EventTouch): void {
        const touches = e.getAllTouches();

        if (touches.length === 0) {
            if (!this._isTouchDragging && this._activeTouchId !== -1) {
                // 无拖拽 → 判定为点击
                e.getUILocation(this._tempUILoc);
                this._convertToTargetLocal(this._tempUILoc.x, this._tempUILoc.y);
                this._bus.emit(
                    HallEvents.INPUT_CLICK,
                    this._targetLocalPos.x,
                    this._targetLocalPos.y
                );
            }
            this._activeTouchId = -1;
            this._isTouchDragging = false;
            this._lastPinchDist = 0;

        } else if (touches.length === 1) {
            // 双指变单指，重置状态
            this._activeTouchId = touches[0].getID();
            this._lastPinchDist = 0;
            this._isTouchDragging = true;
        }
    }

    // =========================================================
    //  鼠标：拖动 / 点击 / 滚轮缩放
    // =========================================================
    private _onMouseDown(e: EventMouse): void {
        if (e.getButton() !== EventMouse.BUTTON_LEFT) return;
        this._isMouseDragging = false; // 按下时还不知道是点击还是拖动
        e.getUILocation(this._touchUIPos);
        this._startUIPos.set(this._touchUIPos.x, this._touchUIPos.y);
    }

    private _onMouseMove(e: EventMouse): void {
        if (!this._isMouseDragging && e.getButton() !== EventMouse.BUTTON_LEFT) {
            // 如果没有按下左键，不处理拖动
            return;
        }

        const delta = e.getUIDelta();
        if (Math.abs(delta.x) > 0 || Math.abs(delta.y) > 0) {
            this._isMouseDragging = true;
            this._bus.emit(HallEvents.INPUT_SINGLE_DRAG, delta.x, delta.y);
        }
    }

    private _onMouseUp(e: EventMouse): void {
        if (e.getButton() !== EventMouse.BUTTON_LEFT) return;

        e.getUILocation(this._touchUIPos);
        const dx = this._touchUIPos.x - this._startUIPos.x;
        const dy = this._touchUIPos.y - this._startUIPos.y;

        this._convertToTargetLocal(this._touchUIPos.x, this._touchUIPos.y);

        if (dx * dx + dy * dy < TAP_TOLERANCE_SQ) {
            // 移动距离很小 → 点击
            this._bus.emit(
                HallEvents.INPUT_CLICK,
                this._targetLocalPos.x,
                this._targetLocalPos.y
            );
        } else {
            // 拖拽结束
            this._bus.emit(
                HallEvents.INPUT_DRAG_END,
                this._targetLocalPos.x,
                this._targetLocalPos.y
            );
        }

        this._isMouseDragging = false;
    }

    private _onMouseWheel(e: EventMouse): void {
        const scrollY = e.getScrollY();
        if (scrollY === 0) return;

        // 向上滚 → 放大，向下滚 → 缩小
        const factor = scrollY > 0 ? 1 + WHEEL_ZOOM_STEP : 1 - WHEEL_ZOOM_STEP;
        this._bus.emit(HallEvents.INPUT_PINCH, factor);
    }

    // =========================================================
    //  坐标转换
    // =========================================================
    private _convertToTargetLocal(uiX: number, uiY: number): void {
        this._inputWorldPos.set(uiX, uiY, 0);
        this._targetUITransform.convertToNodeSpaceAR(
            this._inputWorldPos,
            this._targetLocalPos
        );
    }
}